```ts
const wire = (client: WebSocket): {seen: Wire[]; once: (type: string) => Promise<void>} => {
  const seen: Wire[] = [];
  const waiting = new Map<string, Array<() => void>>();
  const flush = (type: string): void => {
    for (const resume of waiting.get(type) ?? []) resume();
    waiting.delete(type);
  };
  client.on('message', raw => {
    const frame = JSON.parse(String(raw)) as Wire;
    seen.push(frame);
    flush(frame.type);
  });
  return {
    seen,
    once: type => {
      const found = seen.some(frame => frame.type === type);
      if (found) return Promise.resolve();
      return new Promise(resolve => {
        waiting.set(type, [...(waiting.get(type) ?? []), resolve]);
      });
    },
  };
};
```

